        stack = [n]
        op = 0  # 0:'*', 1:'/', 2:'+', 3:'-'
        for i in range(n - 1, 0, -1):
            if op == 0:
                stack[-1] = stack[-1] * i
            elif op == 1:
                # division truncates toward zero
                stack[-1] = int(stack[-1] / i)
